//! `math` generated by `mlirformat tblgen` (`math.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "math.gen.rs"]
mod math;

#[test]
fn math_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<math::Math>();
    common::Fixtures::check_dialect(&opt, "math");
}
